rss.channel:
  {{ site.title }} — price changes
  {{ base_url }}/

  Every recorded pricing change across the AI and SaaS tools we track, as it happens.
  {{ site.lang }}
  {{ now|rfc822 }}
{# 変更が起きた時だけ更新されるフィードは購読する価値がある。
   検索流入に依存しない直接の流入経路になるので、記事一覧ではなく
   変更イベントを流すこと。 #}
{% for item in feed %}


    {{ item.headline }}
    {{ base_url }}/{{ item.path }}
    {{ item.tool.slug }}-{{ item.change.kind }}-{{ item.change.plan }}-{{ item.change.ts }}
    {{ item.when|rfc822 }}
    {{ item.headline }}. Verified against {{ item.tool.name }}'s official pricing page.

{% endfor %}
